### The Go Application (`dns_forwarder.go`)

```go
package main

import (
	"fmt"
	"log"
	"net"
	"sync"
	"time"
)

// DNSForwarder handles incoming DNS requests
type DNSForwarder struct {
	cache map[string][]net.IP
	mu    sync.RWMutex
}

// NewDNSForwarder creates a new instance
func NewDNSForwarder() *DNSForwarder {
	return &DNSForwarder{
		cache: make(map[string][]net.IP),
	}
}

// Resolve forwards a query to Google (8.8.8.8) and Cloudflare (1.1.1.1)
// and stores the result in the cache.
func (d *DNSForwarder) Resolve(host string) ([]net.IP, error) {
	// 1. Define the upstream servers
	upstreamServers := []string{
		"8.8.8.8",
		"1.1.1.1",
	}

	// 2. Try to resolve using the first upstream server
	var ips []net.IP
	var err error

	for _, server := range upstreamServers {
		ips, err = net.LookupIP(host)
		if err == nil && len(ips) > 0 {
			break
		}
	}

	if err != nil {
		return nil, err
	}

	// 3. Store in the cache (Thread-safe write)
	d.mu.Lock()
	d.cache[host] = ips
	d.mu.Unlock()

	return ips, nil
}

// GetCached returns the cached IPs for a host if they exist
func (d *DNSForwarder) GetCached(host string) ([]net.IP, bool) {
	d.mu.RLock()
	defer d.mu.RUnlock()
	ips, exists := d.cache[host]
	return ips, exists
}

// ClearCache removes a specific host from the cache
func (d *DNSForwarder) ClearCache(host string) {
	d.mu.Lock()
	delete(d.cache, host)
	d.mu.Unlock()
}

