```protobuf
syntax = "proto3";

package ansible;

option go_package = "github.com/youruser/ansible-grpc/proto";

// Request to start a playbook
message PlaybookRequest {
  string playbook_path = 1;
  map<string, string> extra_vars = 2;
}

// Response containing the output line
message PlaybookResponse {
  string line = 1;
  bool is_error = 2;
}

// Service definition
service AnsibleService {
  // Unary call to start the job
  rpc RunPlaybook(PlaybookRequest) returns (stream PlaybookResponse);
}
