const uniqueData = this.data.reduce((acc, item) => {
  // Check if we have already seen this company ID
  const existingIndex = acc.findIndex(existing => existing.company.id === item.company.id);

  if (existingIndex !== -1) {
    // Merge logic: Keep the existing item but update dates
    acc[existingIndex] = {
      ...acc[existingIndex],
      startDate: this.$dayjs.min(
        this.$dayjs(acc[existingIndex].startDate),
        this.$dayjs(item.startDate),
      ),
      endDate: this.$dayjs.max(
        this.$dayjs(acc[existingIndex].endDate),
        this.$dayjs(item.endDate),
      ),
    };
  } else {
    // New item: Push to accumulator
    acc.push(item);
  }

  return acc;
}, []);

return uniqueData;
